import {
  getLocalSolvedPuzzleMap,
  PuzzleInfoBox,
  ClickableMonarchDevice,
} from "@hunt/puzzle-components";
import React from "react";

const CAPSTONE_SLUG = "australian_caduceus";

const PuzzleComponent = () => {
  const solvedPuzzles = getLocalSolvedPuzzleMap();

  return CAPSTONE_SLUG in solvedPuzzles ? (
    <div className="flex items-center gap-2">
      <div>
        <p>
          The Serpentine Hills Puzzmon love eating apples (except Oudinenuff,
          who doesn&apos;t need to eat). Can you help them navigate through the
          terrain safely?
        </p>
        <p>
          Some Puzzmon have special abilities, so make sure to use them to your
          advantage!
        </p>
      </div>
      <ClickableMonarchDevice zoneSlug="serpentine_hills" className="w-20" />,
    </div>
  ) : (
    <PuzzleInfoBox copyable={false}>
      You need to solve the{" "}
      <a href={`/puzzles/${CAPSTONE_SLUG}`}>Serpentine Hills capstone puzzle</a>{" "}
      before you can access this task.
    </PuzzleInfoBox>
  );
};

export default PuzzleComponent;
